// ContactStatus — The status of a contact.
type ContactStatus string

const (
	// ContactStatusInvited — Contact was invited.
	ContactStatusInvited ContactStatus = "INVITED"
	// ContactStatusActive — Contact is active.
	ContactStatusActive ContactStatus = "ACTIVE"
	// ContactStatusDeclined — Contact was declined.
	ContactStatusDeclined ContactStatus = "DECLINED"
	// ContactStatusApplied — Contact applied.
	ContactStatusApplied ContactStatus = "APPLIED"
	// ContactStatusBlocked — Contact application was blocked.
	ContactStatusBlocked ContactStatus = "BLOCKED"
)

// ValidContactStatus returns all valid values for ContactStatus.
func ValidContactStatus() []ContactStatus {
	return []ContactStatus{
		ContactStatusInvited,
		ContactStatusActive,
		ContactStatusDeclined,
		ContactStatusApplied,
		ContactStatusBlocked,
	}
}

// ContactStatusFilter — The status for filtering contacts.
type ContactStatusFilter string

const (
	// ContactStatusFilterAvailable — The status is either INVITED or ACTIVE.
	ContactStatusFilterAvailable ContactStatusFilter = "AVAILABLE"
	// ContactStatusFilterUnavailable — The status is not INVITED or ACTIVE.
	ContactStatusFilterUnavailable ContactStatusFilter = "UNAVAILABLE"
)

