// ContractTerminationReason — The reasons for terminating an active contract with a worker.
type ContractTerminationReason string

const (
	// ContractTerminationReasonWorkerUnavailability — The worker is no longer able to fulfil the contract.
	ContractTerminationReasonWorkerUnavailability ContractTerminationReason = "WORKER_UNAVAILABILITY"
	// ContractTerminationReasonProjectCompletedEarly — The project was finished ahead of schedule.
	ContractTerminationReasonProjectCompletedEarly ContractTerminationReason = "PROJECT_COMPLETED_EARLY"
	// ContractTerminationReasonMutualAgreementToTerminate — Both the client and the worker agree to end the contract.
	ContractTerminationReasonMutualAgreementToTerminate ContractTerminationReason = "MUTUAL_AGREEMENT_TO_TERMINATE"
	// ContractTerminationReasonBudgetConstraints — Financial limitations necessitate ending the contract early.
	ContractTerminationReasonBudgetConstraints ContractTerminationReason = "BUDGET_CONSTRAINTS"
	// ContractTerminationReasonChangeInProjectScope — Significant alterations in project requirements or objectives.
	ContractTerminationReasonChangeInProjectScope ContractTerminationReason = "CHANGE_IN_PROJECT_SCOPE"
	// ContractTerminationReasonPerformanceIssues — The work delivered does not meet expected standards.
	ContractTerminationReasonPerformanceIssues ContractTerminationReason = "PERFORMANCE_ISSUES"
	// ContractTerminationReasonCommunicationIssues — Challenges in effective communication between parties.
	ContractTerminationReasonCommunicationIssues ContractTerminationReason = "COMMUNICATION_ISSUES"
	// ContractTerminationReasonPersonalReasons — Personal circumstances affecting the Worker’s ability to work.
	ContractTerminationReasonPersonalReasons ContractTerminationReason = "PERSONAL_REASONS"
	// ContractTerminationReasonLegalOrComplianceIssues — Legal matters or compliance regulations require termination.
	ContractTerminationReasonLegalOrComplianceIssues ContractTerminationReason = "LEGAL_OR_COMPLIANCE_ISSUES"
	// ContractTerminationReasonViolationOfContractTerms — Breach of agreed-upon terms by one of the parties.
	ContractTerminationReasonViolationOfContractTerms ContractTerminationReason = "VIOLATION_OF_CONTRACT_TERMS"
	// ContractTerminationReasonUnforeseenCircumstances — Events beyond control, such as natural disasters or emergencies.
	ContractTerminationReasonUnforeseenCircumstances ContractTerminationReason = "UNFORESEEN_CIRCUMSTANCES"
	// ContractTerminationReasonDissatisfactionWithQualityOfWork — The quality of work is not satisfactory to the client.
	ContractTerminationReasonDissatisfactionWithQualityOfWork ContractTerminationReason = "DISSATISFACTION_WITH_QUALITY_OF_WORK"
	// ContractTerminationReasonConflictOfInterest — A conflict has arisen that affects the working relationship.
	ContractTerminationReasonConflictOfInterest ContractTerminationReason = "CONFLICT_OF_INTEREST"
	// ContractTerminationReasonOther — Any reason not covered above.
	ContractTerminationReasonOther ContractTerminationReason = "OTHER"
)

// ValidContractTerminationReason returns all valid values for ContractTerminationReason.
func ValidContractTerminationReason() []ContractTerminationReason {
	return []ContractTerminationReason{
		ContractTerminationReasonWorkerUnavailability,
		ContractTerminationReasonProjectCompletedEarly,
		ContractTerminationReasonMutualAgreementToTerminate,
		ContractTerminationReasonBudgetConstraints,
		ContractTerminationReasonChangeInProjectScope,
		ContractTerminationReasonPerformanceIssues,
		ContractTerminationReasonCommunicationIssues,
		ContractTerminationReasonPersonalReasons,
		ContractTerminationReasonLegalOrComplianceIssues,
		ContractTerminationReasonViolationOfContractTerms,
		ContractTerminationReasonUnforeseenCircumstances,
		ContractTerminationReasonDissatisfactionWithQualityOfWork,
		ContractTerminationReasonConflictOfInterest,
		ContractTerminationReasonOther,
	}
}

